import React from "react";
import {
  AbsoluteFill,
  Easing,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
} from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type BlurRevealListProps = Record<string, any>;

const BlurRevealList: React.FC<BlurRevealListProps> = ({
  backgroundColor = "#111111",
  transparentBackground = false,
  primaryColor = "#3b82f6",
  textColor = "#ffffff",
  accentColor = "#8b5cf6",
  durationInSeconds = 10,
  items = [
    { text: "Define clear objectives" },
    { text: "Execute with precision" },
    { text: "Analyze results data" },
    { text: "Iterate and improve" },
  ],
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width } = useVideoConfig();

  // Responsive constants calculated once
  const isSmall = width < 600;
  const maxWidth = Math.min(900, width * 0.9);
  const containerPadding = isSmall ? 30 : 60;
  const gapSize = isSmall ? 20 : 36;
  const itemPadding = isSmall ? 12 : 20;
  const fontSize = isSmall ? 24 : 32;

  // Animation timing
  const totalFrames = durationInSeconds * fps;
  const revealDelay = totalFrames / (items.length + 2); 
  const revealDuration = 25; 

  // Safe colors
  const bgColor = transparentBackground ? "transparent" : backgroundColor;
  
  // Performance Optimization: Simplified colors and gradients
  const containerBg = transparentBackground ? "transparent" : `${primaryColor}08`;
  const containerBorder = `${primaryColor}20`;
  const accentGradient = `linear-gradient(90deg, ${primaryColor}, ${accentColor})`;
  
  // Performance Optimization: Disable shadow on transparent export to save render time
  const containerShadow = transparentBackground 
    ? "none" 
    : `0 8px 32px ${primaryColor}10`;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Inter, sans-serif",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      {/* Background Gradient - Only render if opaque to save resources */}
      {!transparentBackground && (
        <AbsoluteFill
          style={{
            background: `linear-gradient(135deg, ${primaryColor}10 0%, transparent 50%, ${accentColor}10 100%)`,
            opacity: 0.3,
            pointerEvents: "none",
          }}
        />
      )}

      {/* Main Card Container */}
      <div
        style={{
          width: maxWidth,
          position: "relative",
          padding: containerPadding,
          backgroundColor: containerBg,
          borderRadius: 24,
          border: `1px solid ${containerBorder}`,
          boxShadow: containerShadow,
          display: "flex",
          flexDirection: "column",
          gap: gapSize,
        }}
      >
        {/* Decorative Top Line */}
        <div
          style={{
            position: "absolute",
            top: 0,
            left: 40,
            right: 40,
            height: 2,
            background: `linear-gradient(90deg, transparent, ${accentColor}, transparent)`,
            opacity: 0.5,
          }}
        />

        {items.map((item, index) => {
          const startFrame = index * revealDelay + 10;
          
          // Single interpolation for main progress
          const progress = interpolate(
            frame,
            [startFrame, startFrame + revealDuration],
            [0, 1],
            {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
              easing: Easing.out(Easing.quad),
            }
          );

          // Derived values
          const opacity = progress; 
          const scale = interpolate(progress, [0, 1], [0.95, 1]);
          const rawBlur = interpolate(progress, [0, 1], [5, 0]);
          const barWidth = interpolate(progress, [0, 1], [0, 100]); 

          // Performance Optimization: 
          // 1. Remove filter entirely when blur is negligible (< 0.5px) to stop browser composition
          // 2. Remove 'will-change' to reduce memory pressure
          const activeFilter = rawBlur > 0.5 ? `blur(${rawBlur}px)` : "none";

          const isVisible = frame > startFrame;
          const isDone = progress === 1;

          return (
            <div
              key={index}
              style={{
                display: "flex",
                alignItems: "center",
                gap: 24,
                padding: itemPadding,
                borderRadius: 16,
                backgroundColor: isVisible ? `${primaryColor}05` : "transparent",
                border: `1px solid ${isVisible ? `${primaryColor}15` : "transparent"}`,
                transform: `scale(${scale})`,
                opacity,
                // Performance Optimization: Removed CSS transition to prevent renderer double-work
                transition: "none",
              }}
            >
              {/* Number Circle */}
              <div
                style={{
                  width: 48,
                  height: 48,
                  flexShrink: 0,
                  borderRadius: "50%",
                  backgroundColor: isDone ? accentColor : `${accentColor}20`,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  fontSize: 24,
                  fontWeight: "700",
                  color: "#FFFFFF",
                  border: `2px solid ${isDone ? accentColor : `${accentColor}40`}`,
                }}
              >
                {index + 1}
              </div>

              {/* Progress Bar Decoration */}
              <div
                style={{
                  flex: 1,
                  height: 4,
                  backgroundColor: `${primaryColor}10`,
                  borderRadius: 2,
                  overflow: "hidden",
                  position: "relative",
                  maxWidth: 100, 
                }}
              >
                <div
                  style={{
                    height: "100%",
                    width: `${barWidth}%`,
                    background: accentGradient,
                  }}
                />
              </div>

              {/* Text Content */}
              <div
                style={{
                  flex: 3,
                  fontSize,
                  fontWeight: "600",
                  color: textColor,
                  filter: activeFilter,
                }}
              >
                {item.text}
              </div>

              {/* Completed Dot Indicator */}
              <div
                style={{
                  width: 10,
                  height: 10,
                  borderRadius: "50%",
                  backgroundColor: accentColor,
                  opacity: isDone ? 1 : 0,
                  transform: `scale(${isDone ? 1 : 0})`,
                }}
              />
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default BlurRevealList;